/** Extract a channel code from any of the public link formats (or a raw code). */
function resolveCode(input) {
  const s = String(input || '').trim();
  if (!s) return null;
  const m = s.match(/(?:whatsapp\.com\/channel|chat\.whatsapp\.com|channels\.whatsapp\.com)\/([A-Za-z0-9]{8,})/);
  if (m) return m[1];
  if (/^[A-Za-z0-9]{16,}$/.test(s)) return s; // raw code
  return null;
}

